        n = len(f)
        Q_f = []
        for i in range(2**n):
            row = []
            for j in range(2**n):
                if f[i] == f[j]:
                    row.append(1)
                else:
                    row.append(-1)
            Q_f.append(row)
        return Q_f

    def arithmetic_rank(Q):
        n = len(Q)
        rank = 0
        for i in range(n):
            pivot = Q[i][i]
            if pivot == 0:
                continue
            for j in range(i + 1, n):
                factor = -Q[j][i] / pivot
                for k in range(n):
                    Q[j][k] += factor * Q[i][k]
            rank += 1
        return rank

    def communication_complexity(f):
