        n = len(f)
        if n <= 1:
            return None
        Q_f = []
        for i in range(n):
            row = []
            for j in range(n):
                if f[i] == f[j]:
                    row.append(0)
                else:
                    row.append(1)
            Q_f.append(row)
        return Q_f

    def arithmetic_rank(Q):
        n = len(Q)
        rank = 0
        for i in range(n):
            pivot_row = None
            for j in range(i, n):
                if Q[j][i] != 0:
                    pivot_row = j
                    break
            if pivot_row is None:
                continue
            rank += 1
            for j in range(n):
                if j == pivot_row:
                    continue
                factor = Fraction(Q[j][i], Q[pivot_row][i])
                for k in range(n):
                    Q[j][k] -= factor * Q[pivot_row][k]
        return rank

    def communication_complexity(f):
        n = len(f)
        if n == 1:
            return 0
        return math.ceil(math.log2(n))

